package com.authcore;
import org.springframework.context.annotation.*;import org.springframework.http.HttpMethod;import org.springframework.security.config.Customizer;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.core.userdetails.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;
@Configuration public class SecurityConfig{
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean UserDetailsService userDetailsService(UserRepository users){return email->users.findByEmail(email.toLowerCase().trim()).map(u->User.withUsername(u.getEmail()).password(u.getPasswordHash()).roles("USER").build()).orElseThrow(()->new UsernameNotFoundException("User not found"));}
 @Bean SecurityFilterChain filterChain(HttpSecurity http)throws Exception{return http.csrf(csrf->csrf.disable()).authorizeHttpRequests(auth->auth.requestMatchers(HttpMethod.POST,"/api/auth/register").permitAll().requestMatchers("/api/auth/health").permitAll().anyRequest().authenticated()).httpBasic(Customizer.withDefaults()).build();}
}